describe('DISCOVERY-V3-005 E2E: DiscoverScreen Integration', () => {
  // Skip if not running E2E tests
  if (!process.env.RUN_SUPABASE_E2E) {
    it.skip('Skipping E2E tests (set RUN_SUPABASE_E2E=true to run)', () => {});
