              : route.name === 'BrowseItems'
              ? 'Browse'Discover'
              ? 'Discover'
              : route.name}
          </Text>
        ),
        tabBarIcon: ({ focused }) => {
          const iconName =
            route.name === 'Dashboard'
              ? 'Dashboard'
              : route.name === 'Discover'
              ? 'Discoverame;
          return <TabIcon name={iconName} focused={focused} />;
        },
